// Extra interview questions per topic, merged in index.ts. `tricky` marks trap questions where the
// obvious answer is wrong. `sql` snippets are shown with the question and run on the playground data.
import type { Interview } from "../types";

export const INTERVIEW_EXTRA: Record<string, Interview[]> = {
  "what-is-a-database": [
    { level: "junior", q: "What is the difference between a database and a DBMS?", a: "The database is the data: the tables, rows and indexes on disk. The DBMS is the software that manages it: Postgres, MySQL, SQLite. People say 'database' for both, but in an interview I keep them apart, because questions about locking, planning and replication are about the DBMS." },
    { level: "mid", tricky: true, q: "Is SQLite a toy database?", a: "No. It is the most deployed database in the world, inside every phone and browser, and it is fully ACID with a real planner and B-tree indexes. What it lacks is a server: one writer at a time and no network access, so it fits embedded apps, tests and local tools, not a multi-user web backend." },
    { level: "mid", tricky: true, q: "The app is slow. Will a bigger database server fix it?", a: "Usually not first. Most slowness is one missing index, an N+1 loop, or a query reading far more pages than it returns. I look at the slow query log and the plan before touching hardware, because a bigger box makes a bad plan slightly less slow at ten times the cost." },
    { level: "junior", tricky: true, sql: "SELECT typeof(1), typeof('1'), typeof(1.5), typeof(NULL), 10 / 4, 10 / 4.0;", q: "What does this return, and what does it teach?", a: "integer, text, real, null, 2 and 2.5. Two lessons: a value has a type even in a loose database, and integer division truncates. 10 / 4 is 2 in SQLite, Postgres and MySQL alike. Multiply by 1.0 or cast before dividing when you want a fraction." },
    { level: "senior", q: "Why do relational databases still dominate after decades of NoSQL?", a: "Because most business data is relational: orders have customers, and invariants span tables. SQL plus constraints and transactions express that directly, the planners are extremely mature, and Postgres absorbed the good ideas: JSONB, full-text, partitioning, logical replication. NoSQL won specific niches, not the general case." },
  ],
  "tables-keys-relationships": [
    { level: "junior", tricky: true, q: "Can a table have two primary keys?", a: "No, one primary key per table, though it can be composite, meaning several columns together. What a table can have is several unique constraints. A candidate key is any column set that could be the primary key; you pick one and declare the others UNIQUE." },
    { level: "mid", tricky: true, q: "Can a foreign key column be NULL?", a: "Yes, unless you add NOT NULL. A NULL foreign key means 'no relationship', for example an employee with no manager. The constraint is only checked for non-NULL values. Whether NULL is allowed is a design decision you must make on purpose." },
    { level: "mid", tricky: true, sql: "SELECT COUNT(*) AS all_rows, COUNT(manager_id) AS with_manager, COUNT(DISTINCT manager_id) AS distinct_managers FROM employees;", q: "Three different counts on the same table. Why do they differ?", a: "COUNT(*) counts rows, so 10. COUNT(manager_id) skips the NULL of the CEO, so 9. COUNT(DISTINCT manager_id) counts unique non-NULL managers, so 4. Interviewers use this to check that you know NULL is skipped by column aggregates." },
    { level: "mid", q: "What is a composite key and when do you use one?", a: "A primary key made of two or more columns, like (product_id, tag) in a join table. I use it when the combination is the identity and nothing else will reference the row. If other tables must point at it, I add a surrogate id and keep the pair as a UNIQUE constraint." },
    { level: "senior", tricky: true, q: "ON DELETE CASCADE makes cleanup easy. Why might you avoid it?", a: "Because a single DELETE can silently wipe a tree of financial or audit rows, and it bypasses application logic like notifications or soft-delete rules. I use CASCADE for true child rows that mean nothing alone, like order_items, and RESTRICT plus soft delete for anything with history." },
  ],
  "data-types-and-constraints": [
    { level: "junior", tricky: true, sql: "SELECT 0.1 + 0.2 = 0.3 AS equal, ROUND(0.1 + 0.2, 2) = 0.3 AS rounded_equal;", q: "Why is the first value 0 and what is the real fix?", a: "0.1 and 0.2 are binary approximations, so their sum is 0.30000000000000004 and the comparison fails. Rounding hides it but is not the fix. For money, the fix is a NUMERIC or DECIMAL column, or integer minor units, so the arithmetic is exact." },
    { level: "mid", tricky: true, q: "VARCHAR(255) versus TEXT in Postgres: which is faster?", a: "Neither. In Postgres they are the same type with an optional length check, and TEXT is idiomatic. The 255 habit comes from old MySQL index limits. I use TEXT plus a CHECK constraint when a real limit matters, like a 2-character country code." },
    { level: "mid", tricky: true, q: "Should you store a phone number as an integer?", a: "No. Leading zeros vanish, plus signs and extensions do not fit, and you never do arithmetic on it. Phone numbers, postcodes, account numbers and IDs from other systems are text. Store them normalised, for example E.164, and validate with a CHECK or in the app." },
    { level: "mid", tricky: true, sql: "SELECT 'Mumbai' = 'mumbai' AS equal_eq, 'Mumbai' LIKE 'mumbai' AS equal_like;", q: "Why do these two give different answers, and is that the same in Postgres?", a: "In SQLite, = is case-sensitive but LIKE is case-insensitive for ASCII, so 0 and 1. Postgres LIKE is case-sensitive and ILIKE is the insensitive one; MySQL depends on the column collation. The lesson: never assume case rules, store a normalised copy or use an expression index on lower(col)." },
    { level: "senior", q: "How would you model a value that must be one of a list that business users edit weekly?", a: "A lookup table with a foreign key, not an enum or CHECK, because adding a value becomes an INSERT instead of a migration, and the table can carry a label, sort order and an active flag. I keep enums for truly fixed sets like order status that code branches on." },
  ],
  "select-filter-sort": [
    { level: "junior", tricky: true, sql: "SELECT name FROM customers WHERE city = NULL;", q: "Why is this always empty, even for rows whose city really is NULL?", a: "Because city = NULL is unknown for every row, including rows where city is NULL, and WHERE keeps only true. The correct test is city IS NULL. Set a customer's city to NULL with an UPDATE and run both forms to see it. This is the most common NULL bug in production code." },
    { level: "junior", tricky: true, sql: "SELECT name, price FROM products WHERE price > 100 OR category = 'Books' AND stock < 160;", q: "Which rows come back and why might that surprise the author?", a: "AND binds tighter than OR, so it reads price > 100 OR (category = 'Books' AND stock < 160). The author probably wanted (price > 100 OR category = 'Books') AND stock < 160. Without parentheses, the headphones at 199 with stock 15 come back regardless of the Books condition." },
    { level: "mid", tricky: true, q: "Does ORDER BY in a subquery or view guarantee the outer result order?", a: "No. SQL sets are unordered; only the outermost ORDER BY counts, and the planner may ignore an inner ORDER BY entirely. MySQL even drops it from views. If I need an order, I put ORDER BY on the final query, and for pagination I make it deterministic with a unique tie-breaker like id." },
    { level: "mid", tricky: true, sql: "SELECT name FROM customers WHERE name LIKE 'a%';", q: "This returns Aarav in SQLite. Will it in Postgres?", a: "No. SQLite's LIKE ignores ASCII case, so 'a%' matches 'Aarav'. Postgres LIKE is case-sensitive, so it returns nothing; you would use ILIKE or lower(name) LIKE 'a%'. Behaviour that differs between engines is a favourite interview trap." },
    { level: "mid", q: "What does DISTINCT actually do and what does it cost?", a: "It removes duplicate output rows after SELECT computes them, usually with a hash or a sort over the whole result. It is cheap for small results and expensive for millions of rows. If I need DISTINCT after a join, I first ask whether the join is fanning out, because that is usually the real bug." },
    { level: "senior", tricky: true, q: "LIMIT 10 without ORDER BY returned different rows after a VACUUM. Is that a bug?", a: "No. Without ORDER BY the database returns whatever ten rows it reaches first, which depends on physical layout, the plan and concurrent activity. VACUUM or a new index changed the path. Any query where order matters needs an explicit ORDER BY with a unique tie-breaker." },
  ],
  "aggregates-group-by": [
    { level: "junior", tricky: true, sql: "SELECT SUM(qty) AS units, COUNT(*) AS rows_found FROM order_items WHERE order_id = 999;", q: "Order 999 does not exist. What comes back?", a: "One row with units NULL and rows_found 0. Aggregates over zero rows return one row; SUM, AVG, MIN and MAX give NULL while COUNT gives 0. Code that adds the SUM to another number gets NULL, so I wrap it in COALESCE(SUM(qty), 0)." },
    { level: "mid", tricky: true, sql: "SELECT manager_id, COUNT(*) AS reports FROM employees GROUP BY manager_id ORDER BY manager_id;", q: "What happens to the CEO's NULL manager_id here?", a: "NULLs form their own group, so there is a row with manager_id NULL and count 1. GROUP BY treats all NULLs as equal, unlike the = operator. That is also why DISTINCT returns a single NULL." },
    { level: "mid", tricky: true, q: "Can you use a column alias from SELECT in GROUP BY?", a: "Postgres and MySQL allow aliases in GROUP BY, standard SQL and SQL Server do not, because GROUP BY logically runs before SELECT. An alias in HAVING is rejected by Postgres. I repeat the expression or use a CTE so the query works everywhere." },
    { level: "mid", tricky: true, q: "What is the difference between COUNT(*) and COUNT(1)?", a: "Nothing in any modern engine: both count rows, and the planner treats them identically. COUNT(column) is the one that differs, because it skips NULLs. The old belief that COUNT(1) is faster is a myth worth saying out loud so the interviewer knows you have checked." },
    { level: "senior", q: "How do you get a per-country total and a grand total in one query?", a: "With GROUP BY ROLLUP (country) in Postgres or MySQL, which adds a final row with NULL country holding the grand total, or GROUPING SETS for custom combinations. Where ROLLUP is unavailable, I UNION ALL a second aggregate. GROUPING() tells a real NULL apart from the subtotal marker." },
  ],
  joins: [
    { level: "junior", tricky: true, sql: "SELECT COUNT(*) FROM orders o JOIN order_items oi ON oi.order_id = o.id WHERE o.id = 1;", q: "One order. Why is the count 2?", a: "Because the join produces one row per matching item, and order 1 has two items. COUNT(*) counts joined rows, not orders. To count orders after a join I use COUNT(DISTINCT o.id), or I aggregate items first." },
    { level: "mid", tricky: true, q: "Is a RIGHT JOIN ever necessary?", a: "No. Any RIGHT JOIN can be rewritten as a LEFT JOIN by swapping the tables, and most teams ban RIGHT JOIN for readability. The only time it appears is in generated SQL or when a long FROM chain makes swapping awkward." },
    { level: "mid", tricky: true, sql: "SELECT c.name, COUNT(o.id) AS orders FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'cancelled' GROUP BY c.id ORDER BY orders DESC, c.name LIMIT 3;", q: "Which customers appear with 0 and why does COUNT(o.id) matter here?", a: "Every customer appears, because the status filter lives in ON and only limits which orders match. Customers with no cancelled orders get NULL order columns, and COUNT(o.id) skips those NULLs, giving 0. COUNT(*) would wrongly give 1 for them." },
    { level: "mid", q: "What is a CROSS JOIN good for?", a: "Generating combinations: every size with every colour for a product grid, or every date in a calendar with every store for a report that must show zeros. I always expect rows multiplied, so I keep both sides small or filter immediately after." },
    { level: "senior", tricky: true, q: "Two tables, both with an index on the join key, and the join is still slow. What next?", a: "I check the plan. Common causes: the planner chose a hash join because one side is large, so the index is irrelevant; the join key types differ so a cast disables the index; or the fan-out produces millions of intermediate rows. Often the fix is to filter earlier or pre-aggregate, not to add more indexes." },
    { level: "senior", q: "Explain a semi-join and how the planner executes EXISTS.", a: "A semi-join returns rows from the left side that have at least one match on the right, without duplicating them. Postgres turns EXISTS and IN with a subquery into a semi-join node and stops probing after the first match, so it is usually faster than a JOIN plus DISTINCT and never changes the row count." },
  ],
  "subqueries-ctes": [
    { level: "junior", tricky: true, sql: "SELECT name FROM employees WHERE id NOT IN (SELECT manager_id FROM employees);", q: "Nine employees are not managers. Why does this return nothing?", a: "The subquery returns the CEO's NULL manager_id. NOT IN expands to id <> 1 AND id <> 2 AND id <> NULL, and comparing with NULL is unknown, so no row passes. The fix is NOT EXISTS or adding WHERE manager_id IS NOT NULL in the subquery." },
    { level: "mid", tricky: true, q: "Is a CTE always materialised?", a: "No. Since Postgres 12 a CTE referenced once is inlined like a subquery, so filters push into it. It is materialised if referenced more than once, if it has side effects, or if I write AS MATERIALIZED. Before 12 every CTE was an optimisation fence, which is why some old advice says CTEs are slow." },
    { level: "mid", tricky: true, sql: "WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 5) SELECT SUM(i) FROM n;", q: "What stops this recursion, and what happens without the WHERE?", a: "The WHERE i < 5 makes the recursive step return no rows at i = 5, which ends the loop, so the sum is 15. Without it the CTE grows forever until memory or a statement timeout stops it. Every recursive CTE needs a termination condition or a depth limit." },
    { level: "mid", q: "What is the difference between a scalar subquery and a correlated one?", a: "A scalar subquery returns exactly one value and runs once, like the overall average. A correlated subquery references the outer row, so conceptually it runs once per row. The planner may turn the correlated form into a join, but I write it as a join or a window when the table is large." },
    { level: "senior", tricky: true, q: "WITH ... UPDATE in Postgres: in what order do the data-modifying CTEs see each other's changes?", a: "They do not. All statements in a WITH run against the same snapshot, so a second CTE cannot see rows inserted by the first in the same query. That makes WITH moved AS (DELETE ... RETURNING *) INSERT INTO archive SELECT * FROM moved work atomically, but chained updates on the same rows behave unexpectedly." },
  ],
  "window-functions": [
    { level: "junior", tricky: true, sql: "SELECT name, salary, ROW_NUMBER() OVER () AS rn FROM employees ORDER BY salary DESC LIMIT 3;", q: "Why are the row numbers not 1, 2, 3?", a: "ROW_NUMBER() OVER () with no ORDER BY inside the window numbers rows in whatever order the scan produced, and the outer ORDER BY sorts afterwards. The window's ORDER BY and the query's ORDER BY are independent. To rank by salary I must write OVER (ORDER BY salary DESC)." },
    { level: "mid", tricky: true, q: "Can you filter on a window function in WHERE?", a: "No. Window functions are computed after WHERE, GROUP BY and HAVING, in the SELECT phase, so WHERE rn = 1 is an error. I put the window in a CTE or subquery and filter in the outer query. Some engines offer QUALIFY, which is exactly this shortcut." },
    { level: "mid", tricky: true, sql: "SELECT day, SUM(1) OVER (ORDER BY day) AS running_rows, SUM(1) OVER (ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rows_strict FROM logins WHERE user_id IN (1, 2) ORDER BY day LIMIT 4;", q: "Two users logged in on 2025-06-01. Why do the two running counts differ on that day?", a: "The default frame is RANGE, which includes all peers with the same ORDER BY value, so both rows for 2025-06-01 get 2. With ROWS the frame ends at the current row, so the first row gets 1 and the second 2. For running totals on non-unique keys I use ROWS or make the order unique." },
    { level: "mid", q: "What is NTILE for?", a: "Splitting ordered rows into N roughly equal buckets: quartiles of customers by spend, deciles of response times. NTILE(4) OVER (ORDER BY spend DESC) labels each row 1 to 4. It differs from PERCENT_RANK, which gives a continuous position between 0 and 1." },
    { level: "senior", q: "Why are window functions usually faster than the equivalent self-join?", a: "A self-join on 'all rows in the same group with a smaller date' creates a quadratic number of intermediate rows before aggregating. A window function sorts the partition once and walks it, so it is linear after the sort. For running totals over millions of rows that is the difference between seconds and hours." },
  ],
  "writing-data": [
    { level: "junior", tricky: true, q: "What is the difference between DELETE, TRUNCATE and DROP?", a: "DELETE removes rows, can have a WHERE, fires triggers and is logged row by row. TRUNCATE empties the whole table in one fast operation, resets identity counters and in Postgres is transactional. DROP removes the table itself, schema and all. Interviewers also ask which is rollback-able: in Postgres all three inside a transaction; in MySQL TRUNCATE and DROP commit implicitly." },
    { level: "mid", tricky: true, sql: "UPDATE products SET stock = stock - 1 WHERE id = 3 AND stock >= 1; SELECT changes() AS rows_changed;", q: "Two of these run at the exact same moment with stock = 1. Can both report 1 row changed?", a: "No. The row lock serialises them: the second UPDATE waits, then re-evaluates stock >= 1 against the committed value 0 and changes nothing. That is why a conditional UPDATE is the safe way to decrement stock, and why the app must check the changed-row count." },
    { level: "mid", tricky: true, q: "Does INSERT ... ON CONFLICT DO NOTHING tell you whether it inserted?", a: "Only if I add RETURNING: it returns the row when it inserted and nothing when it skipped. Without RETURNING the row count is 0 for a skip. I rely on that to branch, for example 'first delivery of this webhook: process it; duplicate: acknowledge and stop'." },
    { level: "mid", q: "How do you insert a million rows quickly?", a: "In batches of a few thousand rows per INSERT or with COPY in Postgres, inside one transaction per batch, with indexes and foreign keys that can be deferred or created afterwards. One row per statement in autocommit is the slowest possible way because every row pays a round trip and an fsync." },
    { level: "senior", tricky: true, q: "An UPDATE of one column on a 100M-row table is running for an hour. What went wrong and what would you do instead?", a: "A single UPDATE rewrites every row version, holds locks the whole time, generates huge WAL and bloat, and replicas fall behind. I would run it in batches by primary-key range with short transactions and a pause between them, or add the column with a default so no rewrite is needed." },
  ],
  normalization: [
    { level: "junior", tricky: true, q: "Is a table with a JSON column automatically not in 1NF?", a: "Strictly, a JSON blob with a list inside breaks 1NF, because a cell holds more than one value. In practice it is a deliberate trade-off for data you never filter or join on. The failure is when you start writing WHERE json->'tags' ? 'x' every day; at that point the tags belong in a table." },
    { level: "mid", tricky: true, q: "Does normalisation make queries faster or slower?", a: "Both. Writes get faster and safer, because one fact lives in one row. Reads that need many tables get slower, because of joins. The classic answer is normalise first for correctness, then denormalise specific hot read paths deliberately, with one code path maintaining the copy." },
    { level: "mid", q: "Give an example of a 2NF violation that a composite key makes easy to spot.", a: "order_items(order_id, product_id, qty, product_name). The key is the pair, but product_name depends on product_id alone. Change a product's name and every order line must change. Moving product_name to products fixes it, or snapshotting it on purpose if invoices must keep the old name." },
    { level: "senior", tricky: true, q: "What is BCNF and when does 3NF fail to be enough?", a: "BCNF requires every determinant to be a candidate key. 3NF lets a non-key column determine part of a composite key, which can still duplicate data. The classic case is a table of (student, course, tutor) where each tutor teaches one course: tutor determines course, so the course repeats per student. Splitting into (tutor, course) and (student, tutor) fixes it." },
    { level: "senior", q: "How do you find duplication in an existing schema quickly?", a: "I look for columns whose values repeat together across rows, like city and country, or any column named like another table's attribute, like customer_city on orders. SELECT a, COUNT(DISTINCT b) ... HAVING COUNT(DISTINCT b) > 1 finds facts that already disagree, which is the proof the table needs splitting." },
  ],
  "real-world-schema-patterns": [
    { level: "mid", tricky: true, q: "Is a (target_type, target_id) polymorphic column pair a good way to link comments to posts or photos?", a: "It is common but the database cannot enforce it: no foreign key can point at two tables. I prefer nullable post_id and photo_id with a CHECK that exactly one is set, or a comments table per target. The pair is acceptable only when referential integrity is handled elsewhere and the targets are many." },
    { level: "mid", tricky: true, q: "You added deleted_at for soft delete. What breaks in your UNIQUE constraints?", a: "A deleted user still occupies their email, so re-registration fails. The fix is a partial unique index WHERE deleted_at IS NULL, so uniqueness applies to live rows only. Every lookup also needs the deleted_at filter, which I hide in a view or ORM scope." },
    { level: "senior", q: "How do you store an order's status history and the current status without them drifting apart?", a: "The events table is the truth: order_events(order_id, from, to, at, by), inserted in the same transaction as the UPDATE of orders.status. A nightly check compares the last event with the column. Some teams derive status purely from events, but a cached column keeps the common queries fast." },
    { level: "senior", tricky: true, q: "Why is updating a balance column in place a problem for a wallet?", a: "It loses history and invites lost updates. Two concurrent transfers that read and write the same balance can overwrite each other unless locked, and you cannot explain how the number got there. An append-only ledger with debit and credit rows, summed for the balance and locked in id order, gives correctness and an audit trail." },
    { level: "senior", q: "How do you design tags that users can create freely but admins can merge later?", a: "tags(id, name UNIQUE, canonical_id NULL) plus item_tags(item_id, tag_id). Merging sets canonical_id on the duplicate and repoints item_tags in one transaction. Queries resolve through COALESCE(canonical_id, id). A plain text array column cannot be merged without rewriting every row." },
  ],
  "ids-and-migrations": [
    { level: "junior", tricky: true, q: "Why not just RENAME COLUMN in production?", a: "Because the old application code is still running during a rolling deploy, and it breaks the instant the rename lands. Adding the new column, dual-writing, backfilling, switching reads and dropping the old column later lets every release work with the schema before and after it." },
    { level: "mid", tricky: true, q: "ADD COLUMN ... NOT NULL DEFAULT 'web' on a 500M-row table: safe or not?", a: "In Postgres 11 and later, yes: a constant default is stored in the catalogue and rows are not rewritten. Before 11, or with a volatile default like now(), it rewrites the table under a lock. MySQL depends on the version and whether INSTANT ALTER applies. Know your engine version before answering." },
    { level: "mid", q: "What does CREATE INDEX CONCURRENTLY cost compared with a plain CREATE INDEX?", a: "It does not block writes, but it scans the table twice, waits for all running transactions, takes longer, cannot run inside a transaction block, and if it fails it leaves an invalid index that must be dropped. I use it for every index on a live table and check pg_index.indisvalid afterwards." },
    { level: "senior", tricky: true, q: "A migration that only adds a nullable column froze the site for five minutes. How?", a: "The ALTER needed an ACCESS EXCLUSIVE lock and waited behind a long-running transaction. While it waited, every new query on that table queued behind it, so even a metadata-only change caused an outage. The fix is lock_timeout with retry, and killing idle-in-transaction sessions before DDL." },
    { level: "senior", q: "How do you run data backfills safely alongside a live application?", a: "In batches by primary-key range, each in its own short transaction, with a sleep between batches so replicas and autovacuum keep up, idempotent so a restart can resume, and monitored by rows per second and replication lag. Large backfills run from a job, never inside the migration that the deploy waits on." },
  ],
  indexes: [
    { level: "junior", tricky: true, q: "Does adding an index always make a query faster?", a: "No. It helps only when the query filters, joins or sorts on the indexed columns in a shape the index can serve, and when the filter is selective. For a condition matching most rows, the planner correctly prefers a scan. Meanwhile every index slows every write and takes space." },
    { level: "mid", tricky: true, sql: "EXPLAIN QUERY PLAN SELECT * FROM orders WHERE status = 'paid';", q: "There is no index on status, so this scans. Would an index on status be a good idea?", a: "Probably not: with four statuses, a value like 'paid' matches a large share of rows, so an index would be ignored or barely help. A composite like (customer_id, status) or a partial index for a rare status such as 'pending' is the useful shape." },
    { level: "mid", tricky: true, q: "Why can an UPDATE that does not touch the indexed column still be slowed down by indexes in Postgres?", a: "Because an UPDATE writes a new row version, and unless the new version fits on the same page so a HOT update applies, every index must get a new entry pointing at it. Tables with many indexes and full pages pay this on every update, which is why I keep fill factor and index count under control." },
    { level: "mid", q: "What is an index-only scan and why can it still touch the table?", a: "When every needed column is in the index, Postgres reads just the index. But row visibility lives in the heap, so it checks the visibility map and visits the heap page for any page not marked all-visible. After heavy writes and before VACUUM, an index-only scan degrades into many heap fetches." },
    { level: "senior", tricky: true, q: "Two indexes: (a) and (a, b). Is (a) redundant?", a: "Usually yes, because (a, b) serves any query on a alone through the leftmost prefix. Exceptions: (a) is much smaller so scans on a alone are cheaper, or (a) is unique and enforces a constraint. I drop the redundant one after checking pg_stat_user_indexes shows it unused." },
    { level: "senior", q: "When would you choose a BRIN index?", a: "For huge append-only tables where the column correlates with physical order, like created_at on an events table. BRIN stores min and max per block range, so it is tiny and lets range queries skip whole regions. It is useless on randomly ordered columns and weak for point lookups." },
  ],
  "reading-query-plans": [
    { level: "junior", tricky: true, q: "The plan shows cost=12000. Is that milliseconds?", a: "No. Cost is a unit-less estimate in the planner's own scale, roughly 'sequential page reads', used only to compare candidate plans. Real time comes from EXPLAIN ANALYZE. A plan with a lower cost can run slower if the estimates are wrong." },
    { level: "mid", tricky: true, q: "EXPLAIN ANALYZE on a DELETE: what happens?", a: "It really runs the DELETE, because ANALYZE executes the statement to measure it. I wrap it in BEGIN ... ROLLBACK, or use EXPLAIN without ANALYZE for writes. Interviewers ask this to see whether you have deleted production rows by accident." },
    { level: "mid", q: "What is a Bitmap Heap Scan?", a: "Postgres uses one or more indexes to build a bitmap of matching page ids, then reads those pages in physical order. It sits between an index scan and a sequential scan in selectivity, avoids random IO, and is how the planner combines two indexes for an OR condition with BitmapOr." },
    { level: "senior", tricky: true, q: "Estimated rows match actual rows, the plan looks right, but the query is still slow. Where do you look?", a: "At buffers and timing per node: shared read versus hit shows cold cache or too much data; a sort spilling to disk shows low work_mem; lock waits show in the wait events, not in the plan; and a fast plan with high execution time may be returning megabytes over the network. The plan is only part of the story." },
    { level: "senior", q: "What are extended statistics and when do you create them?", a: "Statistics on combinations of columns, created with CREATE STATISTICS, so the planner stops assuming columns are independent. If city and country are correlated, multiplying their selectivities underestimates rows by orders of magnitude and picks nested loops. I add them when estimated rows are far from actual on multi-column filters." },
  ],
  "query-antipatterns": [
    { level: "junior", tricky: true, q: "Why is SELECT * harmful even when you need most columns?", a: "It returns columns you do not use, including wide text or JSON, defeats covering indexes, silently changes when columns are added, and breaks positional code. Naming columns also documents intent. The exception is ad-hoc exploration, not application code." },
    { level: "mid", tricky: true, q: "Is OFFSET pagination always wrong?", a: "No. For small result sets, admin screens and page numbers users must jump to, OFFSET is fine. It is wrong for infinite scroll over large tables and for feeds where inserts shift rows. Keyset pagination fixes cost and stability but cannot jump to page 500 directly." },
    { level: "mid", tricky: true, sql: "SELECT name FROM customers WHERE id IN (SELECT customer_id FROM orders WHERE status = 'paid') ORDER BY name LIMIT 5;", q: "Is IN with a subquery an anti-pattern? What does the planner do here?", a: "No, IN with a subquery is fine: the planner turns it into a semi-join and never has the NULL problem that NOT IN has. The anti-pattern is NOT IN with a nullable column, and IN with a huge literal list from the app, which should be a temp table or an ANY($1) array." },
    { level: "mid", q: "How do you spot N+1 in a GraphQL API?", a: "Resolvers for a list field fire one query per parent: 100 posts, 100 author queries. I log query counts per request and alert when the count scales with list size. DataLoader batches the ids within one tick into a single WHERE id = ANY($1) query, and persisted queries make the batching predictable." },
    { level: "senior", tricky: true, q: "A developer replaced a slow OR with UNION and it got faster. Was the OR really the problem?", a: "Partly. OR across different columns can defeat a single index, and UNION lets each branch use its own index. But Postgres can often do the same with a BitmapOr, so the real question is why it did not: stale statistics or non-sargable branches. UNION also deduplicates, which costs a sort; UNION ALL plus a DISTINCT key is usually what they wanted." },
  ],
  "pooling-caching-app-layer": [
    { level: "junior", tricky: true, q: "Max connections is 100 and you have 5 app servers. What pool size per server?", a: "Not 100 divided by 5. I leave headroom for migrations, admin tools and replicas, so something like 10 to 15 per server, and I measure wait time. If more concurrency is needed, PgBouncer in transaction mode multiplexes many client connections over few server connections." },
    { level: "mid", tricky: true, q: "Why does PgBouncer in transaction mode break prepared statements and session settings?", a: "Because a client gets a different server connection for each transaction, so anything stored on the connection, named prepared statements, SET commands, advisory session locks, temp tables, is not there next time. Drivers must use unnamed statements or protocol-level prepare support, and settings go in SET LOCAL inside the transaction." },
    { level: "mid", q: "What is a cache stampede and how do you prevent it?", a: "A popular key expires and hundreds of requests miss at once and all rebuild it from the database. I prevent it with a short lock so one request rebuilds while others wait or serve stale, with jittered TTLs so keys do not expire together, and with background refresh for the hottest keys." },
    { level: "mid", tricky: true, q: "Is it safe to cache a user's permissions in Redis for an hour?", a: "Only if revocation can tolerate an hour, which it usually cannot. I either invalidate on every permission change by deleting the user's key, or keep the TTL short, or cache a version number that changes on revoke. Security-relevant data gets explicit invalidation, not TTL alone." },
    { level: "senior", q: "Where should a transaction boundary live in a Nest or Express app?", a: "In the service layer, around exactly the database operations that must succeed together, with the client passed down to repositories. Not in controllers, which should not know about transactions, and not around external calls. I use a withTx helper so BEGIN, COMMIT, ROLLBACK and release are impossible to forget." },
  ],
  "acid-in-practice": [
    { level: "junior", tricky: true, q: "If I run a single UPDATE without BEGIN, is it in a transaction?", a: "Yes. Autocommit wraps every statement in its own transaction, so a single UPDATE is atomic and durable on its own. BEGIN only matters when several statements must succeed or fail together. People sometimes think single statements can be half-applied; they cannot." },
    { level: "mid", tricky: true, q: "A constraint error happened on the second statement of a Postgres transaction. Can you catch it and continue?", a: "Not directly: the whole transaction is in an aborted state and every further statement fails until ROLLBACK. To continue, I need a SAVEPOINT before the risky statement and ROLLBACK TO it. MySQL and SQLite let the other statements proceed, which is why portable code always rolls back on error." },
    { level: "mid", q: "What does COMMIT guarantee if synchronous_commit is off?", a: "Atomicity and consistency still hold, but durability becomes 'within a few hundred milliseconds'. A crash right after COMMIT can lose the last commits, while the database stays consistent. I use it per transaction for low-value writes like logs or metrics, never for money." },
    { level: "senior", tricky: true, q: "Is a transaction enough to prevent overselling stock?", a: "Not by itself. Two transactions can both read stock = 1, both decide to sell, and both commit under READ COMMITTED. Atomicity does not add serialisation. I need a conditional UPDATE, a row lock with SELECT FOR UPDATE, or SERIALIZABLE. 'Just wrap it in a transaction' is the trap answer." },
    { level: "senior", q: "How long can a transaction safely stay open?", a: "Milliseconds to low seconds. Longer transactions hold row locks that block writers, pin old row versions so VACUUM cannot clean, and keep a pooled connection busy. I set idle_in_transaction_session_timeout and statement_timeout, and never hold a transaction across user input or an external HTTP call." },
  ],
  "isolation-levels": [
    { level: "junior", tricky: true, q: "Does READ COMMITTED prevent lost updates?", a: "No. Two transactions can each read the same value, compute in the app, and both write; the second overwrites the first. READ COMMITTED only stops dirty reads. Preventing lost updates takes an atomic UPDATE expression, a version check, SELECT FOR UPDATE, or a higher isolation level." },
    { level: "mid", tricky: true, q: "Is REPEATABLE READ in MySQL the same as REPEATABLE READ in Postgres?", a: "No. Both give a consistent snapshot for plain reads, but Postgres detects concurrent updates and raises a serialization error, while InnoDB lets the UPDATE proceed on the latest committed row, so a lost update is still possible unless you use FOR UPDATE. InnoDB also uses gap locks that Postgres does not have." },
    { level: "mid", q: "What happens to a SELECT under SERIALIZABLE in Postgres: does it block writers?", a: "No. Postgres uses serializable snapshot isolation, so readers never block and writers never block readers. Instead, it tracks read-write dependencies and aborts a transaction when a cycle would make the schedule non-serialisable. The cost is retries, not blocking." },
    { level: "senior", tricky: true, q: "Would putting the whole app on SERIALIZABLE be a safe default?", a: "Safe for correctness, costly in practice: more aborts under contention, every code path must retry, and predicate locking has overhead. I use READ COMMITTED with explicit locks or atomic updates for the few hot invariants, and SERIALIZABLE for specific transactions like booking or allocation where write skew is possible." },
    { level: "senior", q: "Explain the difference between a non-repeatable read and a phantom read with a schema example.", a: "Non-repeatable: I read account 1's balance twice in one transaction and it changed because someone updated that row. Phantom: I count accounts with balance over 100 twice and the count changed because someone inserted a new matching row. Row versioning fixes the first; preventing the second needs predicate or range protection, which Postgres snapshots provide for reads." },
  ],
  "locks-mvcc-deadlocks": [
    { level: "junior", tricky: true, q: "Does a SELECT take a lock in Postgres?", a: "A plain SELECT takes only a weak table lock that prevents the table being dropped, no row locks, thanks to MVCC. SELECT ... FOR UPDATE or FOR SHARE takes row locks. In MySQL under SERIALIZABLE, plain SELECTs do take shared locks, which is a notable difference." },
    { level: "mid", tricky: true, q: "A UNIQUE constraint prevents duplicates, so why can an INSERT still block?", a: "When two transactions insert the same key, the second must wait to learn whether the first commits or rolls back, because the constraint result depends on it. So uniqueness checks serialise concurrent inserts of the same value. That is expected; it is also why ON CONFLICT is atomic." },
    { level: "mid", q: "What is lock escalation and does Postgres do it?", a: "Lock escalation is when a database replaces many row locks with one table lock to save memory, as SQL Server does, which suddenly blocks everyone. Postgres does not escalate; row locks are stored in the row header, so it can lock millions of rows at the cost of writing them." },
    { level: "senior", tricky: true, q: "Deadlocks disappeared after you added ORDER BY id to the locking SELECT. Why did that work?", a: "Both transactions now acquire locks on the same rows in the same order, so one simply waits for the other instead of each holding what the other needs. Consistent lock ordering removes the cycle that defines a deadlock. Without the ORDER BY, the planner could lock rows in different orders per execution." },
    { level: "senior", q: "What is an advisory lock and when is it better than a row lock?", a: "An application-defined lock on a number, taken with pg_advisory_xact_lock(key), independent of any row. I use it to serialise work that has no natural row, like 'only one worker imports tenant 42 at a time' or a cron job that must not run twice. It is released at commit, costs nothing on disk, and avoids inventing a lock table." },
  ],
  "storage-internals": [
    { level: "junior", tricky: true, q: "Does a DELETE immediately free disk space?", a: "No. It marks row versions dead; VACUUM makes the space reusable inside the table, and only VACUUM FULL or pg_repack returns it to the OS. A table that had 100 GB deleted usually stays 100 GB on disk and simply stops growing as new rows reuse the space." },
    { level: "mid", tricky: true, q: "Why is SELECT COUNT(*) slow on a big Postgres table even with an index?", a: "Because of MVCC: row visibility is per transaction and stored in the heap, so the database must check each row version. An index-only scan can help if the visibility map is fresh, but it still touches every entry. For approximate counts I read pg_class.reltuples; for exact counts I maintain a counter." },
    { level: "mid", q: "What is the WAL used for besides crash recovery?", a: "Streaming replication ships WAL to replicas; point-in-time recovery replays archived WAL; logical decoding turns it into change events for CDC tools like Debezium. One sequential log powers durability, copies and integration, which is why WAL volume is a key metric." },
    { level: "senior", tricky: true, q: "Why can updating one small boolean column on a wide row be expensive in Postgres?", a: "Because an UPDATE writes a whole new version of the row, including the wide columns, and if the row does not fit on the same page it must update every index too. Hot flags on wide rows cause bloat and WAL volume. I move frequently updated columns into a narrow side table." },
    { level: "senior", q: "What is TOAST and when does it matter?", a: "The Oversized Attribute Storage Technique: values larger than about 2 KB are compressed and stored out of line in a TOAST table, fetched only when the column is read. It makes SELECT * on tables with big JSON or text columns much slower than selecting the small columns, and it is why wide columns do not bloat the main heap." },
  ],
  "replication-failover-backups": [
    { level: "junior", tricky: true, q: "Is a nightly pg_dump an adequate backup for a payments database?", a: "No. The recovery point is up to 24 hours, so a crash at 23:00 loses a day of payments. I need continuous WAL archiving with base backups, giving point-in-time recovery to seconds, plus tested restores and backups stored in a different region from the primary." },
    { level: "mid", tricky: true, q: "If synchronous replication guarantees no data loss, why not always use it?", a: "Every commit waits for a network round trip to the replica, and if the replica goes down, commits stall until a timeout or until another sync candidate takes over. It also does not help if both nodes share the same failure domain. I use it for data where loss is unacceptable and keep candidates in different zones." },
    { level: "mid", q: "What is logical replication and how is it different from streaming replication?", a: "Streaming replication copies the physical WAL, so the replica is a byte-identical read-only copy of the same major version. Logical replication decodes row changes and publishes them, so subscribers can be different versions, replicate a subset of tables, or feed Kafka through CDC. Logical is more flexible and more work to operate." },
    { level: "senior", tricky: true, q: "After an automatic failover, the old primary came back. What must not happen?", a: "It must not accept writes again, or you get split brain with two divergent histories. Fencing makes it read-only or shuts it down, and it is re-added as a replica with pg_rewind or a fresh base backup. Any commits it took after the partition and before fencing are lost or must be reconciled." },
    { level: "senior", q: "How do you test backups without touching production?", a: "A scheduled job restores the latest base backup plus WAL to a scratch instance, replays to a chosen timestamp, runs integrity checks and a few known queries, records how long it took, and alerts on failure. The restore time is the real RTO, and an untested backup is just a file that might be a backup." },
  ],
  "partitioning-and-sharding": [
    { level: "junior", tricky: true, q: "Does partitioning make every query faster?", a: "No. Queries that filter on the partition key skip partitions and get faster; queries that do not must open every partition and can get slower, especially with hundreds of partitions. Partitioning is for size, retention and maintenance, and only speeds up queries shaped around the key." },
    { level: "mid", tricky: true, q: "Why can't you put a global UNIQUE constraint on a partitioned Postgres table?", a: "Each partition has its own indexes, and Postgres cannot check uniqueness across them. A unique constraint must include the partition key so uniqueness is local to one partition. For a truly global key, I enforce it elsewhere, for example by generating it from a sequence or a UUID." },
    { level: "mid", q: "How do you pick between hash and range sharding?", a: "Hash spreads load evenly and makes point lookups cheap but turns range queries into scatter-gather. Range keeps related keys together and supports ranges but creates hot shards for recent data. Most SaaS shards by tenant with a directory, which is really range-by-tenant with manual placement." },
    { level: "senior", tricky: true, q: "Your sharded system needs a report across all tenants. What do you do?", a: "Not a cross-shard JOIN at request time. I either scatter the query to every shard and merge in the app, acceptable for small results, or stream changes from all shards via CDC into a warehouse built for cross-tenant analytics. Sharding is for the OLTP path; analytics belongs in a different store." },
    { level: "senior", q: "What is a hot shard and how do you fix one?", a: "A shard receiving far more load than the others, usually because one tenant or one key is huge. Fixes: move that tenant to its own shard via the directory, split the tenant's data by a secondary key, cache its hot reads, or use virtual shards so the range can be rebalanced without moving everyone." },
  ],
  "distributed-consistency": [
    { level: "junior", tricky: true, q: "Does 'eventually consistent' mean the data might be wrong?", a: "It means copies may be stale for a while, not that they will be wrong forever: all replicas converge to the same state once writes stop. The risk is decisions made on stale reads, like double-spending a balance. Those reads must go to the leader; stale is fine for feeds and counters." },
    { level: "mid", tricky: true, q: "Kafka guarantees exactly-once delivery, so do I still need idempotent consumers?", a: "Yes. Exactly-once in Kafka covers the stream processing boundary with transactions; the moment a consumer writes to an external database or calls an API, a crash between the side effect and the offset commit redelivers. Idempotency keys on the side effect are what make it safe end to end." },
    { level: "mid", q: "What is the difference between an outbox and a change data capture stream?", a: "The outbox is a table you write to explicitly in the same transaction as the business row, then publish from. CDC reads the database's own WAL and publishes every change without application code. CDC can publish outbox rows too, replacing the polling relay. Outbox gives you intentional, well-shaped events; raw CDC gives you table changes." },
    { level: "senior", tricky: true, q: "Why is two-phase commit considered harmful in microservices even though it gives atomicity?", a: "It holds locks on every participant while waiting for all votes, so one slow or dead participant blocks everyone, and a coordinator crash leaves participants in doubt. Across services with different databases and HTTP APIs, that coupling is worse than the problem. Sagas trade atomicity for availability with explicit compensations." },
    { level: "senior", q: "How do you design an idempotency key store so it cannot itself cause duplicates?", a: "The key is a unique column written in the same transaction as the business effect, with ON CONFLICT DO NOTHING RETURNING to detect the first writer. The stored response is saved before commit. Concurrent duplicates serialise on the unique index. Keys expire after a window, and the client must generate them before the first attempt, not on retry." },
  ],
  "sql-vs-nosql": [
    { level: "junior", tricky: true, q: "Is MongoDB faster than Postgres?", a: "Not in general. Both are fast when the data shape matches the access pattern and indexes exist. MongoDB wins when you read whole documents by key; Postgres wins for joins, aggregates and constraints. Benchmarks that show one 'ten times faster' usually compare a document read with an unindexed join." },
    { level: "mid", tricky: true, q: "Redis is single-threaded. Isn't that slow?", a: "No, it is why Redis is fast and simple: commands run atomically without locks, and everything is in memory, so one core handles hundreds of thousands of operations per second. The limits are memory and the fact that one slow command, like KEYS on a huge keyspace, blocks everything behind it." },
    { level: "mid", q: "How do transactions work in MongoDB and what do they cost?", a: "Multi-document transactions exist since 4.0 on replica sets and 4.2 on sharded clusters, with snapshot isolation and a default 60-second limit. They cost more than single-document writes, which are already atomic, and cross-shard ones coordinate across nodes. If a design needs them on every request, the data probably belonged in a relational table." },
    { level: "senior", tricky: true, q: "A team wants to store orders in Postgres and search them in Elasticsearch. What is the hardest part?", a: "Keeping the two in sync. Dual writes drift the moment one fails. I feed Elasticsearch from the database through the outbox or CDC, treat the index as derived data that can be rebuilt, make indexing idempotent on the order id, and accept seconds of lag. The search index is never the source of truth." },
    { level: "senior", q: "When is Postgres JSONB not enough and a document database is justified?", a: "When documents are large and updated in place frequently, when the working set must scale horizontally with automatic sharding, or when the team's whole access pattern is key-based reads of nested documents with no joins. Even then I check whether Citus or partitioning plus JSONB would do, because one database is cheaper to run than two." },
  ],
  "classic-hard-sql-problems": [
    { level: "mid", tricky: true, sql: "SELECT name, salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1;", q: "Is this the second-highest salary?", a: "Only when there are no ties. If two people share the top salary, OFFSET 1 returns the second of them, not the next distinct salary. DENSE_RANK() OVER (ORDER BY salary DESC) = 2 is the correct answer, and it also returns everyone at that level." },
    { level: "mid", tricky: true, sql: "SELECT c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.status = 'cancelled') ORDER BY c.name;", q: "Does this return customers who never cancelled, or customers with no orders at all?", a: "Both: anyone without a cancelled order, including customers who never ordered. NOT EXISTS on a condition is 'no row matches', which is vacuously true for customers with zero orders. If the question wants customers who ordered and never cancelled, add EXISTS (any order) as a second condition." },
    { level: "senior", tricky: true, sql: "SELECT user_id, COUNT(*) AS days, MAX(day) AS last_day FROM logins GROUP BY user_id HAVING COUNT(*) >= 5;", q: "Is this the 'logged in 5 days in a row' query?", a: "No, it counts 5 login days in any pattern. Consecutiveness needs the gaps-and-islands trick: subtract ROW_NUMBER from the date so consecutive days share a constant, then group by that constant. This is the most common wrong answer to the streak question." },
    { level: "senior", q: "How do you find the median without a MEDIAN function?", a: "Number rows with ROW_NUMBER ordered by the value, get the count with COUNT() OVER (), and keep rows whose number is (count+1)/2 or (count+2)/2, averaging them. That handles odd and even counts. In Postgres I use percentile_cont(0.5) WITHIN GROUP (ORDER BY value)." },
    { level: "senior", q: "Write the idea for 'customers whose spend increased every month for three months'.", a: "Aggregate spend per customer per month, then use LAG twice over the months per customer to get the previous two values, and keep rows where current > previous > previous-before. Any 'rising for N periods' question is LAG N−1 times, or a window COUNT of increases over a frame." },
  ],
  "system-design-with-databases": [
    { level: "mid", tricky: true, q: "The interviewer says 'we expect 10 million users'. Does that mean you shard from day one?", a: "No. 10 million users is a few tens of GB of profile data, which one Postgres handles easily. What matters is write rate and hot queries. I size the primary, add replicas and caching, partition the big event tables, and design the schema so a tenant or user key could shard later if measurements demand it." },
    { level: "senior", tricky: true, q: "For a URL shortener, why not use an auto-increment id as the short code?", a: "It works technically, base62 of the id is short and unique, but it is guessable, so anyone can enumerate every link and infer your volume. I either encode the id with a secret permutation, or generate random codes with a unique index and retry on collision, which costs one extra query occasionally." },
    { level: "senior", q: "How would you store a like count that is read a million times a minute?", a: "Not COUNT(*) per read. A counter in Redis incremented on each like, served from cache, and flushed periodically into a post_stats row in Postgres which is the durable truth. The likes table stays append-only for auditing and recomputation. Reads tolerate a few seconds of lag; writes stay cheap." },
    { level: "senior", tricky: true, q: "In a system design answer, when is it wrong to say 'add a cache'?", a: "When the problem is correctness or write throughput: caching does not fix lost updates, slow inserts or a bloated table, and it adds staleness. Caching is for repeated reads of the same data. I say what I would cache, how it is invalidated, and what happens on a miss storm; a bare 'add Redis' is a red flag." },
    { level: "senior", q: "How do you estimate whether a workload fits on one Postgres primary?", a: "Writes per second times rows per write against roughly ten thousand simple transactions per second on good hardware, working-set size against RAM so hot pages stay cached, and the number of indexes per hot table. If the hot working set fits in memory and writes are under a few thousand per second, it fits, and reads scale with replicas." },
  ],
};
